module SI5345_SET #(
	parameter				p_ge_board				= 1 , // board type for si5345 setting: 1: GE baord; 0: 100GE Board
	parameter				p_center_1				= 0 , // device type for si5345 setting: 1: Center-1, 0: others
	parameter				p_simulation			= 0	  // simulation parameter
	)
	(
	// Clock&Reset
	input					clk							, // (i) clock (100MHz)
	input					rst							, // (i) reset

	// I2C I/F
	inout					i2c_scl						, // (o) I2C clcok output
	inout					i2c_sda						, // (io)I2C data

	// si5345 set complete
	output					dbg_set_complete			  // (o) si5345 setting complete
);

	// -------------------------------------------------------------
	// Parameter definition
	// -------------------------------------------------------------
	// The I2C address is 11010 [A1] [A0]  = 1101011
	parameter				p_id_adr    			= 7'b1101011;	//

	// -------------------------------------------------------------
	// Internal signal definition
	// -------------------------------------------------------------
	// FSM
	parameter				p_idle		 			= 7'b0000001; // idle
	parameter				p_check		 			= 7'b0000010; // check cmd type
	parameter				p_reg_wr	 			= 7'b0000100; // write si5345 register
	parameter				p_reg_wait				= 7'b0001000; // wait write complete
	parameter				p_wait_300ms 			= 7'b0010000; // wait 300ms for si5345 require
	parameter				p_adr_add	 			= 7'b0100000; // register buffer address ++
	parameter				p_complete	 			= 7'b1000000; // si5345 setting complete
	reg		[ 6:0]			r_fsm								; // FSM

	reg		[28:0]			r_pwon_wait							; // wait counter
	wire					s_wait_tout							; // wait count out
	reg		[ 9:0]			r_ram_adr							; // buffer address

	reg						r_reg_wreq							; // register write request
	reg		 [15:0]			r_reg_wadr							; // register write address
	reg		 [31:0]			r_reg_wdat							; // register write data
	wire					s_reg_busy							; // register write busy (I2C)
	wire					s_reg_err 							; // register write error(I2C)
	wire					s_reg_done							; // register write done (I2C)

	// debug signals
	reg						r_dbg_set_complete					; // si5345 setting complete

	// si5345 setting map
	reg		[17:0]			r_cfg_ram[543:0]					; // register map

// =============================================================================
// RTL Body
// =============================================================================

	// -------------------------------------------------------------
	// si5345 register setting map
