		r_cfg_ram[  0]	<= ( p_ge_board == 1 )? { 1'b1, 1'b1, 8'h01, 8'h0B } : ( p_center_1 == 1 )? { 1'b1, 1'b1, 8'h01, 8'h0B } : { 1'b1, 1'b1, 8'h01, 8'h0B } ; // -- set page ------	----------------------  ------------------------
