		r_cfg_ram[538]	<= ( p_ge_board == 1 )? { 1'b1, 1'b1, 8'h01, 8'h05 } : ( p_center_1 == 1 )? { 1'b1, 1'b1, 8'h01, 8'h05 } : { 1'b1, 1'b1, 8'h01, 8'h05 } ; // -- set page ------	---------------------	-----------------------------
		r_cfg_ram[539]	<= ( p_ge_board == 1 )? { 1'b1, 1'b1, 8'h40, 8'h00 } : ( p_center_1 == 1 )? { 1'b1, 1'b1, 8'h40, 8'h00 } : { 1'b1, 1'b1, 8'h40, 8'h00 } ; // 0x0540,0x00        // 0x0540,0x00        // 0x0540,0x00
		r_cfg_ram[540]	<= ( p_ge_board == 1 )? { 1'b1, 1'b1, 8'h01, 8'h0B } : ( p_center_1 == 1 )? { 1'b1, 1'b1, 8'h01, 8'h0B } : { 1'b1, 1'b1, 8'h01, 8'h0B } ; // -- set page ------	---------------------	-----------------------------
		r_cfg_ram[541]	<= ( p_ge_board == 1 )? { 1'b1, 1'b1, 8'h24, 8'hC3 } : ( p_center_1 == 1 )? { 1'b1, 1'b1, 8'h24, 8'hC3 } : { 1'b1, 1'b1, 8'h24, 8'hC3 } ; // 0x0B24,0xC3        // 0x0B24,0xC3        // 0x0B24,0xC3
		r_cfg_ram[542]	<= ( p_ge_board == 1 )? { 1'b1, 1'b1, 8'h25, 8'h02 } : ( p_center_1 == 1 )? { 1'b1, 1'b1, 8'h25, 8'h02 } : { 1'b1, 1'b1, 8'h25, 8'h02 } ; // 0x0B25,0x02        // 0x0B25,0x02        // 0x0B25,0x02
		r_cfg_ram[543]	<= ( p_ge_board == 1 )? { 1'b0, 1'b0, 8'h00, 8'h00 } : ( p_center_1 == 1 )? { 1'b0, 1'b0, 8'h00, 8'h00 } : { 1'b0, 1'b0, 8'h00, 8'h00 } ; // End
	end

	// -------------------------------------------------------------
	// wait/delay time counter
	// -------------------------------------------------------------
	// Delay 300 msec
	//    Delay is worst case time for device to complete any calibration
	//    that is running due to device state change previous to this script
	//    being processed.
	always @( posedge clk or posedge rst ) begin
		if ( rst == 1'b1 ) begin
            r_pwon_wait		<=  29'h002D_C6C0 ;			// ÉÏµçµÈ´ý30ms = 30 x 1000us x 100MHz = 28'h002D_C6C0
		end else begin
			if ( r_fsm == p_check ) begin
				r_pwon_wait		<=  29'h01C9_C380 ;		// ÒÀ¾ÝSi5345ÅäÖÃÒªÇóµÈ´ý300 ms = 300 x 1000us x 100MHz = 28'h01C9_C380
			end else if ( r_fsm == p_idle || r_fsm == p_wait_300ms ) begin
				r_pwon_wait		<= r_pwon_wait - 1'b1 ;
			end
		end
	end

	assign s_wait_tout	= r_pwon_wait[28] ;

	// -------------------------------------------------------------
	// SI5326 register write
	// -------------------------------------------------------------
	// FSM for si5345 setting
	always @( posedge clk or posedge rst ) begin
		if ( rst == 1'b1 ) begin
			r_fsm			<= p_idle			;
		end else begin
			case ( r_fsm )
				p_idle		: begin
					if ( s_wait_tout == 1'b1 ) begin
						r_fsm	<= p_check;				// poweron wait 30ms£¬start si5345 setting
					end
				end

				p_check		: begin
					if ( r_cfg_ram[r_ram_adr][17:16] == 2'b11 ) begin
						if ( s_reg_busy == 1'b0 ) begin
							r_fsm	<= p_reg_wr;					// ÅÐ¶ÏÃüÁî=11£¬Îª¼Ä´æÆ÷Ð´²Ù×÷£¬µÈ´ýIC½Ó¿Úbusy=0 ½øÐÐ¼Ä´æÆ÷Ð´²Ù×÷
						end
					end else if ( r_cfg_ram[r_ram_adr][17:16] == 2'b10 ) begin
						r_fsm	<= p_wait_300ms;					// ÅÐ¶ÏÃüÁî=10£¬ÎªµÈ´ýÃüÁî£¬µÈ´ý300ms

					end else begin
						r_fsm	<= p_complete;						// ÅÐ¶ÏÃüÁî=ÆäËûÖµ£¬Îª½áÊøÃüÁî£¬ÅäÖÃ½áÊø
					end
				end

				p_reg_wr	: begin
					r_fsm		<= p_reg_wait;						// Ð´¼Ä´æÆ÷
				end

				p_reg_wait	: begin
					if ( s_reg_done == 1'b1 ) begin
						r_fsm	<= p_adr_add;						// Ð´¼Ä´æÆ÷Íê³É
					end
				end

				p_wait_300ms : begin
					if ( s_wait_tout == 1'b1 ) begin
						r_fsm	<= p_adr_add;						// µÈ´ý300ms
					end
				end

				p_adr_add	: begin
					r_fsm	<= p_check;								// ¼Ä´æÆ÷bufferµØÖ·+1£¬´¦ÀíÏÂÒ»¸öÃüÁî
				end

				p_complete	: begin
					r_fsm	<= p_complete;							// ÅäÖÃÍê³É
				end

				default		: begin
					r_fsm		<= p_idle;							// Òì³£×´Ì¬£¬·µ»Øidle
				end
			endcase
		end
	end

	// I2C write control
	always @( posedge clk or posedge rst ) begin
		if ( rst == 1'b1 ) begin
			r_reg_wreq		<= 1'b0  ;
			r_reg_wadr		<= 16'b0 ;
			r_reg_wdat		<= 32'b0 ;
		end else begin
			if ( r_fsm == p_reg_wr ) begin
				r_reg_wreq		<= 1'b1 ;													// write request
				r_reg_wadr		<= { p_id_adr,  1'b0, r_cfg_ram[r_ram_adr][15 : 8] }	;	// Slave ID & RNW & address
				r_reg_wdat		<= {           24'b0, r_cfg_ram[r_ram_adr][ 7 : 0] }	;	// write data
			end else begin
				r_reg_wreq		<= 1'b0 ;
			end
		end
	end

	// register buffer address
	always @( posedge clk or posedge rst ) begin
		if ( rst == 1'b1 ) begin
			r_ram_adr	<= 10'b0 ;
		end else begin
			if ( r_fsm == p_idle ) begin
				r_ram_adr	<= 10'b0 ;
			end else if ( r_fsm == p_adr_add ) begin
				r_ram_adr	<= r_ram_adr + 1'b1 ;		// address +1
			end
		end
	end

	// -------------------------------------------------------------
	// I2C Master Interface
	// -------------------------------------------------------------
	I2C_MASTER #(
		.P_SIMULATION			( p_simulation			)  // simulation parameter
		)
	U_I2C_MASTER (
		// clock & reset
		.RST        		    ( rst					), // (i) Global reset
		.CLK       		        ( clk					), // (i) Global clock
		// register interface signals
		.R2H_WREQ               ( r_reg_wreq			), // (i) write request
		.R2H_WADR               ( r_reg_wadr			), // (i) write address
		.R2H_WDAT               ( r_reg_wdat			), // (i) write data
		.R2H_RREQ               ( 1'b0					), // (i) read request
		.R2H_RADR               ( 16'b0					), // (i) read address
		.R2H_RDAT               ( 						), // (o) read data
		.R2H_BUSY    		    ( s_reg_busy			), // (o) access busy
		.R2H_ERR     		    ( s_reg_err 			), // (o) access error
		.R2H_DONE    		    ( s_reg_done			), // (o) access done
		// I2C bus control signals
		.I2C_SCL                ( i2c_scl				), // (i) I2C clock
		.I2C_SDA                ( i2c_sda				)  // (i) I2C serial data input
		) ;

	// -------------------------------------------------------------
	// Debug begin vvvvv
	// -------------------------------------------------------------
	always @( posedge clk ) begin
		if ( r_fsm == p_complete ) begin
			r_dbg_set_complete	<= 1'b1	;
		end else begin
			r_dbg_set_complete	<= 1'b0	;
		end
	end

	assign dbg_set_complete	= ( p_simulation == 0 )? r_dbg_set_complete : 1'b1 ;
	// -------------------------------------------------------------
	// Debug end ^^^^^
	// -------------------------------------------------------------

endmodule